package chat
import("context";"os";"path/filepath";"encoding/json";"errors";"reflect";"strings";"sync";"testing";"github.com/madkoding/kitties/internal/connector")
type stagedMetadataConnector struct{kind string;calls int;args map[string]any;bad bool;onCall func()}
func(f *stagedMetadataConnector)Kind()string{return f.kind};func(f *stagedMetadataConnector)Describe()string{return "synthetic metadata only"}
func(f *stagedMetadataConnector)Call(_ context.Context,args map[string]any)(string,error){f.calls++;if f.onCall!=nil{f.onCall()};f.args=map[string]any{};for k,v:=range args{f.args[k]=v};if f.bad{return "reflected-private-provider-text",errors.New("reflected-private-provider-error")};raw,_:=json.Marshal(map[string]any{"schema":"lexopen-cloud-metadata.v1","service":f.kind,"action":args["action"],"items":[]map[string]any{{"kind":"folder","name":"folder.pdf"},{"kind":"file","name":"actual.pdf"}},"page_only":true,"exhaustive":false,"items_truncated":false});return string(raw),nil}
func metadataChatFixture(t *testing.T,kind,act string)(*Service,*stagedLocalFleet,*scripted,*stagedMetadataConnector,string,StagedMetadataAction){s,d,brain,_,id,old:=stagedChatFixture(t);provider:="dropbox";if kind=="microsoft-365"{provider="microsoft"};name:="altazor-"+provider+"-0123456789abcdef";k,_:=d.Get(old.Kitty);k.Connectors=[]string{name};c:=&stagedMetadataConnector{kind:kind};d.conns.Add(name,c);args:=map[string]any{"limit":"5"};if act=="search"{q:="pdf";if kind=="microsoft-365"{q=".pdf"};args["query"]=q};return s,d,brain,c,id,StagedMetadataAction{RequestID:"metadata-exact-one",Kitty:k.ID,Connector:name,Action:act,Args:args,Text:"Muéstrame sólo los nombres de hasta cinco PDF de mi cuenta."}}
func TestLexOpenStagedMetadataNoModelExactQueryOneUseAndNoFiles(t *testing.T){for _,kind:=range []string{"dropbox","microsoft-365"}{for _,act:=range []string{"list","search"}{t.Run(kind+act,func(t *testing.T){s,d,brain,c,id,body:=metadataChatFixture(t,kind,act);brain.replies=[]string{"el criterio solicitado"};first,e:=s.StageMetadataAction(context.Background(),id,body);if e!=nil||first.State!="pending"||c.calls!=0||len(brain.seen)!=0||d.calls!=0{t.Fatal("staging performed IO or model")};again,e:=s.StageMetadataAction(context.Background(),id,body);if e!=nil||again!=first{t.Fatal("same request not idempotent")};ap,_:=s.approvals.Get(first.ApprovalID);if !ap.MetadataStageReady||ap.FileStageReady||ap.StructuredReceipt!=nil{t.Fatal("metadata represented as verified file")};if _,e=s.DecideApproval(context.Background(),ap.ID,true,"",true);e==nil||c.calls!=0{t.Fatal("always approval permitted")};done,e:=s.DecideApproval(context.Background(),ap.ID,true,"",false);if e!=nil||done.MetadataReceipt==nil||done.MetadataReceipt.State!="metadata_ready"||done.StructuredReceipt!=nil{t.Fatal("no distinct metadata receipt")};r:=done.MetadataReceipt;if r.RequestID!=body.RequestID||r.ChatID!=id||r.Kitty!=body.Kitty||r.Connector!=body.Connector||r.Kind!=kind||r.Action!=act||r.ApprovalID!=ap.ID||!reflect.DeepEqual(r.Target,body.Args)||r.Bytes!=len([]byte(done.Result))||len(r.SHA256)!=64{t.Fatal("lost exact receipt scope")};want:=map[string]any{"action":act};for k,v:=range body.Args{want[k]=v};if c.calls!=1||!reflect.DeepEqual(c.args,want)||d.calls!=0||len(brain.seen)!=0{t.Fatal("wrong query, model, file transfer or duplicate provider call")};sess,_:=s.Get(id);if len(sess.Turns)!=3||sess.Turns[0].Text!=body.Text||sess.Turns[0].MetadataRequestID!=body.RequestID||sess.Turns[2].From!="approval"||!strings.Contains(sess.Turns[2].Text,"Authorized file read completed. Source service: "+kind+"; action: "+act)||!strings.Contains(sess.Turns[2].Text,done.Result)||len(sess.Turns[2].Calls)!=1||sess.Turns[2].Calls[0].Output!=done.Result||len(sess.Turns[2].Artifacts)!=0{t.Fatal("missing original task or authoritative approval JSON")};if _,e=s.DecideApproval(context.Background(),ap.ID,true,"",false);e==nil||c.calls!=1{t.Fatal("approval replayed")};again,e=s.StageMetadataAction(context.Background(),id,body);if e!=nil||again.State!="metadata_ready"||c.calls!=1{t.Fatal("completed stage replayed")}})}}}
func TestLexOpenStagedMetadataRejectsBindingDriftAndUnselected(t *testing.T){s,d,_,c,id,body:=metadataChatFixture(t,"dropbox","search");first,e:=s.StageMetadataAction(context.Background(),id,body);if e!=nil{t.Fatal(e)};changed:=body;changed.Args=map[string]any{"query":"other","limit":"5"};if _,e=s.StageMetadataAction(context.Background(),id,changed);!errors.Is(e,ErrAsyncConflict)||c.calls!=0{t.Fatal("same id changed arguments")};k,_:=d.Get(body.Kitty);k.Connectors=nil;if _,e=s.DecideApproval(context.Background(),first.ApprovalID,true,"",false);e==nil||c.calls!=0{t.Fatal("removed selection executed")};if _,e=s.DecideApproval(context.Background(),first.ApprovalID,false,"",false);e!=nil||c.calls!=0{t.Fatal("reject reached provider")}}
func TestLexOpenStagedMetadataInvalidArgsAndAliasFailBeforeIO(t *testing.T){for _,alter:=range []func(*StagedMetadataAction){func(b *StagedMetadataAction){b.Args["path"]="/x"},func(b *StagedMetadataAction){b.Args["token"]="fixture"},func(b *StagedMetadataAction){b.Args["action"]="search"},func(b *StagedMetadataAction){b.Args["limit"]="51"},func(b *StagedMetadataAction){b.Args["query"]=""},func(b *StagedMetadataAction){b.Connector="altazor-dropbox-abcdef0123456789"},func(b *StagedMetadataAction){b.Action="download_file"}}{s,_,brain,c,id,b:=metadataChatFixture(t,"dropbox","search");alter(&b);if _,e:=s.StageMetadataAction(context.Background(),id,b);!errors.Is(e,ErrStagedMetadataInvalid)||c.calls!=0||len(brain.seen)!=0{t.Fatal("invalid/foreign request escaped preflight")}}}
func TestLexOpenStagedMetadataFailureSanitizedAndNotReplayed(t *testing.T){s,d,_,c,id,b:=metadataChatFixture(t,"dropbox","search");c.bad=true;a,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil{t.Fatal(e)};done,e:=s.DecideApproval(context.Background(),a.ApprovalID,true,"",false);if e!=nil||done.Error==""||done.Result!=""||done.MetadataReceipt!=nil||strings.Contains(done.Error,"reflected-private")||d.calls!=0{t.Fatal("unsafe failed metadata receipt")};if _,e=s.DecideApproval(context.Background(),a.ApprovalID,true,"",false);e==nil||c.calls!=1{t.Fatal("failed metadata action replayed")}}
func TestLexOpenStagedMetadataConcurrentApprovalExecutesOnce(t *testing.T){s,_,_,c,id,b:=metadataChatFixture(t,"dropbox","search");a,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil{t.Fatal(e)};var wg sync.WaitGroup;for range 8{wg.Add(1);go func(){defer wg.Done();s.DecideApproval(context.Background(),a.ApprovalID,true,"",false)}()};wg.Wait();if c.calls!=1{t.Fatal("concurrent approval duplicated provider call")}}
var _ connector.Connector=(*stagedMetadataConnector)(nil)

func TestLexOpenStagedMetadataNewRequestWaitsForPendingExactReplayAllowed(t *testing.T){s,_,_,c,id,b:=metadataChatFixture(t,"dropbox","search");first,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil{t.Fatal(e)};other:=b;other.RequestID="second-request";if _,e=s.StageMetadataAction(context.Background(),id,other);!errors.Is(e,ErrBusy){t.Fatal("new user goal interleaved pending metadata")};again,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil||again!=first||c.calls!=0{t.Fatal("exact replay was blocked or executed")};sess,_:=s.Get(id);if len(sess.Turns)!=2{t.Fatal("blocked new goal appended user turn")};if _,e=s.DecideApproval(context.Background(),first.ApprovalID,false,"",false);e!=nil{t.Fatal(e)};if _,e=s.StageMetadataAction(context.Background(),id,other);e!=nil{t.Fatal("new goal still blocked after rejection")}}

func TestLexOpenStagedMetadataHistoryFailureIsUnknownWithoutReplay(t *testing.T){s,d,brain,c,id,b:=metadataChatFixture(t,"dropbox","search");a,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil{t.Fatal(e)};c.onCall=func(){path:=filepath.Join(s.dir,id+".json");if e:=os.Remove(path);e!=nil{t.Fatal(e)};if e:=os.Mkdir(path,0700);e!=nil{t.Fatal(e)}};if _,e=s.DecideApproval(context.Background(),a.ApprovalID,true,"",false);!errors.Is(e,ErrStagedMetadataUnavailable){t.Fatal("unsaved approval turn reported success")};if c.calls!=1||d.calls!=0||len(brain.seen)!=0{t.Fatal("history failure triggered IO/replay/model")};again,e:=s.StageMetadataAction(context.Background(),id,b);if e!=nil||again.State!="unknown"||c.calls!=1{t.Fatal("missing authoritative turn marked ready or replayed")};if _,e=s.DecideApproval(context.Background(),a.ApprovalID,true,"",false);e==nil||c.calls!=1{t.Fatal("ambiguous result approval replayed")}}
